const C = { cyan:0x8bdcff, blue:0x2f96d7, teal:0x45d9c8, amber:0xffb55d, red:0xff596b, green:0x70e9aa, dark:0x081016, metal:0x4f626e, concrete:0x5f6669 };
const TAU = Math.PI*2;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lerp=(a,b,t)=>a+(b-a)*t;
const v3=(x=0,y=0,z=0)=>new THREE.Vector3(x,y,z);
const distXZ=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
const smooth=(dt,s=12)=>1-Math.exp(-s*dt);
const $=id=>document.getElementById(id);

