class SaveManager{
  constructor(){this.key='project-eclipse-save-v2';this.fallback={mission:1,objective:0,player:{x:0,y:1.1,z:62,health:100,stamina:100,energy:100},inventory:{'Energy Cell':0,'Research Document':0,'ECLIPSE ARCHIVE':0},collectibles:[],upgrades:{health:0,stamina:0,resistance:0,damage:0,efficiency:0,recharge:0,scanRadius:0,scanDuration:0},relays:{},circuits:{},settings:{graphics:'HIGH',master:.82,music:.72,sfx:.86,uiScale:1,reducedMotion:false,subtitles:true}};this.data=this.read()}
  read(){try{const r=localStorage.getItem(this.key);if(r)return {...this.fallback,...JSON.parse(r)};}catch{}return structuredClone(this.fallback)}
  get(){return this.data}
  write(){try{localStorage.setItem(this.key,JSON.stringify(this.data))}catch{}}
  update(fn){fn(this.data);this.write()}
  reset(){this.data=structuredClone(this.fallback);this.write()}
  hasSave(){try{return !!localStorage.getItem(this.key)}catch{return false}}
  addItem(n,nv=1){this.update(d=>d.inventory[n]=(d.inventory[n]||0)+nv)}
  addCollectible(id){this.update(d=>{if(!d.collectibles.includes(id))d.collectibles.push(id)})}
}

class AudioEngine{
  constructor(){this.ctx=null;this.master=.82;this.music=.72;this.sfx=.86;this.ambience=.8;this.nodes=[];this.combat=false;this.started=false}
  unlock(){if(this.started)return;try{this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.started=true;this.ambient();}catch{}}
  gain(v){const g=this.ctx.createGain();g.gain.value=v;g.connect(this.ctx.destination);return g}
  tone(freq,dur,type='sine',gain=.04,detune=0){if(!this.ctx)return;const o=this.ctx.createOscillator(),g=this.gain(gain*this.master*this.sfx);o.type=type;o.frequency.value=freq;o.detune.value=detune;o.connect(g);const t=this.ctx.currentTime;o.start(t);g.gain.setValueAtTime(gain*this.master*this.sfx,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.stop(t+dur)}
  noise(dur=.12,gain=.03,filter=1200){if(!this.ctx)return;const n=this.ctx.createBufferSource(),b=this.ctx.createBuffer(1,this.ctx.sampleRate*dur,this.ctx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;n.buffer=b;const f=this.ctx.createBiquadFilter();f.type='bandpass';f.frequency.value=filter;const g=this.gain(gain*this.master*this.sfx);n.connect(f).connect(g);n.start();n.stop(this.ctx.currentTime+dur)}
  ui(){this.tone(640,.07,'triangle',.025);this.tone(980,.09,'triangle',.018,5)}
  pickup(){this.tone(720,.08,'sine',.045);setTimeout(()=>this.tone(1040,.12,'sine',.035),70)}
  confirm(){this.tone(520,.1,'sine',.04);setTimeout(()=>this.tone(780,.16,'sine',.04),75)}
  error(){this.tone(190,.18,'sawtooth',.045);this.noise(.1,.02,500)}
  shot(){this.tone(180,.06,'triangle',.06);this.tone(820,.08,'sine',.035);this.noise(.05,.015,2600)}
  impact(){this.noise(.07,.032,1100);this.tone(120,.07,'square',.02)}
  hurt(){this.tone(90,.16,'sawtooth',.04);this.noise(.14,.018,700)}
  alarm(){for(let i=0;i<3;i++)setTimeout(()=>this.tone(260+i*65,.18,'square',.018),i*190)}
  puzzle(){this.tone(440,.09,'sine',.035);setTimeout(()=>this.tone(660,.12,'sine',.04),90);setTimeout(()=>this.tone(990,.22,'sine',.045),190)}
  foot(step){this.noise(.055,.012,step==='metal'?1500:step==='concrete'?900:500)}
  ambient(){if(!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain(),f=this.ctx.createBiquadFilter();o.type='sine';o.frequency.value=46;f.type='lowpass';f.frequency.value=140;g.gain.value=.007*this.master*this.ambience;o.connect(f).connect(g).connect(this.ctx.destination);o.start();this.nodes.push(o);this.ambientLfo=g}
  setMix(combat){this.combat=combat;if(this.ambientLfo)this.ambientLfo.gain.setTargetAtTime((combat?.012:.007)*this.master*this.ambience,this.ctx.currentTime,.3);if(combat){this.tone(130,.35,'sine',.025);this.tone(196,.5,'triangle',.018)}}
}

class Input{
  constructor(canvas){this.keys=new Set();this.mouse={x:0,y:0,dx:0,dy:0,down:false,aim:false};this.touch={mx:0,my:0,lx:0,ly:0,fire:false,aim:false};this.lock=false;window.addEventListener('keydown',e=>{this.keys.add(e.code)});window.addEventListener('keyup',e=>this.keys.delete(e.code));canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>this.pointerDown(e));window.addEventListener('pointerup',e=>this.pointerUp(e));window.addEventListener('pointermove',e=>this.pointerMove(e));}
  pointerDown(e){if(e.pointerType!=='mouse')return;if(document.pointerLockElement===document.querySelector('#game canvas'))this.mouse.down=e.button===0;else if(e.button===0){try{document.querySelector('#game canvas').requestPointerLock()}catch{}}this.mouse.aim=e.button===2}
  pointerUp(e){if(e.pointerType!=='mouse')return;if(e.button===0)this.mouse.down=false;if(e.button===2)this.mouse.aim=false}
  pointerMove(e){if(document.pointerLockElement===document.querySelector('#game canvas')){this.mouse.dx+=e.movementX;this.mouse.dy+=e.movementY}}
  down(k){return this.keys.has(k)}
  clearDelta(){this.mouse.dx=0;this.mouse.dy=0}
  setKey(k,v){v?this.keys.add(k):this.keys.delete(k)}
}

function mat(color,roughness=.7,metalness=.05,emissive=0x000000,ei=0){return new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:ei})}
function box(w,h,d,material,shadow=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);if(shadow){m.castShadow=true;m.receiveShadow=true}return m}
function cyl(r,h,material,radial=10){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,radial),material);m.castShadow=true;m.receiveShadow=true;return m}
function sphere(r,material,segments=12){const m=new THREE.Mesh(new THREE.SphereGeometry(r,segments,Math.max(8,Math.floor(segments*.75))),material);m.castShadow=true;m.receiveShadow=true;return m}
function makeCanvasTexture(seed=1, metal=false){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');let s=seed>>>0;const rnd=()=>((s=(1664525*s+1013904223)>>>0)/4294967296);x.fillStyle=metal?'#33424a':'#64676a';x.fillRect(0,0,128,128);for(let i=0;i<260;i++){const a=Math.floor(rnd()*18)+8, g=metal?Math.floor(40+rnd()*45):Math.floor(80+rnd()*45);x.fillStyle=`rgba(${g},${g+Math.floor(rnd()*8)},${g+Math.floor(rnd()*10)},${.2+rnd()*.5})`;x.fillRect(rnd()*128,rnd()*128,a*.8,a*.25)}for(let i=0;i<9;i++){x.fillStyle=metal?'rgba(180,205,215,.08)':'rgba(255,255,255,.04)';x.fillRect(rnd()*128,0,1+rnd()*4,128)}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(1.8,1.8);return t}

class VFX{
  constructor(scene){this.scene=scene;this.particles=[]}
  burst(pos,color=0x7fdcff,count=18,spread=1.2){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.055,5,5),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));m.position.copy(pos);const vel=v3((Math.random()-.5)*spread,Math.random()*spread,(Math.random()-.5)*spread);this.scene.add(m);this.particles.push({m,vel,life:.35+Math.random()*.5,max:.35+Math.random()*.5})}}
  ring(pos,color=0x80ddff,r=.3){const g=new THREE.RingGeometry(r*.75,r,32);const m=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.75,side:THREE.DoubleSide});const o=new THREE.Mesh(g,m);o.rotation.x=-Math.PI/2;o.position.copy(pos);this.scene.add(o);this.particles.push({m:o,vel:v3(0,.3,0),life:.6,max:.6,ring:true})}
  update(dt){for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;p.m.position.addScaledVector(p.vel,dt);p.vel.y-=2.2*dt;if(p.ring){p.m.scale.multiplyScalar(1+dt*2);p.m.material.opacity=Math.max(0,p.life/p.max)}else{p.m.material.opacity=Math.max(0,p.life/p.max)}if(p.life<=0){this.scene.remove(p.m);p.m.geometry.dispose();p.m.material.dispose();this.particles.splice(i,1)}}}
}

class World{
  constructor(scene){this.scene=scene;this.interactables=[];this.colliders=[];this.region='NORTH RIDGE';this.materials={stone:mat(0x52585d,.96,0),dark:mat(0x16232a,.55,.72),metal:mat(0x566a72,.38,.78),floor:mat(0x283238,.9,.2),concrete:mat(0x64676a,.96,0),glass:mat(0x6cb8cc,.12,.35,0x2ba7c4,.18),cyan:mat(0x66cfff,.28,.25,0x36a8df,3),amber:mat(0xd18e55,.45,.2,0xff8738,2),red:mat(0x9b3f48,.45,.2,0xff2432,2)};this.build();}
  add(o){this.scene.add(o);return o}
  collider(x,z,w,d,y=0,h=6){this.colliders.push({x,z,w,d,y,h})}
  interact(id,label,pos,action){const g=new THREE.Group();g.position.copy(pos);const r=new THREE.Mesh(new THREE.RingGeometry(.45,.58,24),new THREE.MeshBasicMaterial({color:C.cyan,transparent:true,opacity:.16,side:THREE.DoubleSide}));r.rotation.x=-Math.PI/2;g.add(r);g.userData.id=id;g.userData.baseScale=1;this.add(g);const data={id,label,object:g,action,enabled:true};this.interactables.push(data);return data}
  build(){
    const groundTex=makeCanvasTexture(4,false);this.materials.ground=mat(0x535c58,.98,0);this.materials.ground.map=groundTex;
    const terrain=new THREE.Mesh(new THREE.PlaneGeometry(260,220,48,48),this.materials.ground);terrain.rotation.x=-Math.PI/2;terrain.position.y=-.4;terrain.receiveShadow=true;const pa=terrain.geometry.attributes.position;for(let i=0;i<pa.count;i++){const x=pa.getX(i),y=pa.getY(i);pa.setZ(i,(Math.sin(x*.055)+Math.cos(y*.047))*2.4+Math.sin(x*.18+y*.12)*.45)}terrain.geometry.computeVertexNormals();this.add(terrain);
    // mountainous backdrop
    for(let i=0;i<22;i++){const a=i/22*TAU,r=78+(i%3)*10,h=24+(i%5)*9;const rock=sphere(1,this.materials.stone,9);rock.scale.set(9+(i%4)*3,h,8+(i%5)*2);rock.position.set(Math.cos(a)*r,-2,Math.sin(a)*r-12);this.add(rock)}
    this.buildFacility();this.buildExteriorDetails();this.buildUnderground();
    // sky dome
    const sky=new THREE.Mesh(new THREE.SphereGeometry(180,24,16),new THREE.MeshBasicMaterial({color:0x07111a,side:THREE.BackSide,depthWrite:false}));this.add(sky);
  }
  buildFacility(){const concreteTex=makeCanvasTexture(22,false);this.materials.wall=mat(0x697074,.78,.12);this.materials.wall.map=concreteTex;
    const main=box(50,12,32,this.materials.wall);main.position.set(0,5,-20);this.add(main);this.collider(0,-20,50,32,0,12);
    const roof=box(52,1.2,34,this.materials.dark);roof.position.set(0,11.6,-20);this.add(roof);
    for(let i=-2;i<=2;i++){const stripe=box(0.24,8,30,this.materials.cyan,false);stripe.position.set(i*9,5,-4.1);stripe.rotation.y=Math.PI/2;this.add(stripe)}
    const front=box(20,7,2.2,this.materials.dark);front.position.set(0,3.5,-4);this.add(front);
  }
  buildExteriorDetails(){
    for(let i=0;i<14;i++){const p=box(1.1,1.1,1.1,this.materials.metal);p.position.set(-26+Math.random()*52,.6,-54-Math.random()*34);p.rotation.y=Math.random()*TAU;p.rotation.z=(Math.random()-.5)*.4;this.add(p)}
    // towers, road, vents, warning frames
    for(const x of [-24,24]){const tower=new THREE.Group();for(let y=0;y<20;y+=2.8){const leg=cyl(.14,2.8,this.materials.metal,6);leg.position.set(x+(y%5===0?.9:0),y+1,-12);tower.add(leg)}for(const z of [-1,1]){const beam=box(3.8,.16,.2,this.materials.metal);beam.position.set(x,9,-12+z);tower.add(beam)}const beacon=new THREE.Mesh(new THREE.SphereGeometry(.32,10,8),this.materials.red);beacon.position.set(x,20,-12);tower.add(beacon);this.add(tower)}
    const road=box(18,.16,100,this.materials.dark,false);road.position.set(0,-.2,42);this.add(road);for(let z=5;z<92;z+=8){const strip=box(.5,.02,3,this.materials.amber,false);strip.position.set(0,.03,z);this.add(strip)}
    for(let i=0;i<10;i++){const pipe=cyl(.16,Math.random()*11+6,this.materials.metal,8);pipe.rotation.z=Math.PI/2;pipe.rotation.y=Math.random()*.1;pipe.position.set((Math.random()-.5)*44,2+Math.random()*5,-10-(Math.random()*24));this.add(pipe)}
    this.interact('gate','OPEN HELIX GATE',v3(0,1,-4));this.interact('relay-a','ACTIVATE RELAY A',v3(-17,1,8));this.interact('relay-b','ACTIVATE RELAY B',v3(17,1,14));this.interact('relay-c','ACTIVATE RELAY C',v3(0,1,-47));this.interact('tower-uplink','ACCESS UPLINK ARRAY',v3(26,1,-12));this.interact('elevator','USE SERVICE ELEVATOR',v3(0,1,-9));
  }
  buildUnderground(){const floor=box(70,.8,82,this.materials.floor);floor.position.set(0,-20,12);this.add(floor);const ceiling=box(70,.8,82,this.materials.dark);ceiling.position.set(0,9,12);this.add(ceiling);for(let z=-24;z<=48;z+=12){for(const x of [-32,32]){const pillar=box(2,29,2,this.materials.concrete);pillar.position.set(x,-5,z);this.add(pillar)}const light=box(2,.12,1.4,this.materials.cyan,false);light.position.set(0,8.5,z);this.add(light)}
    for(let i=0;i<9;i++){const x=(i%3-1)*19,z=-18+Math.floor(i/3)*22;const wall=box(1.2,14,18,this.materials.wall);wall.position.set(x,-5,z);this.add(wall);this.collider(x,z,1.2,18,-20,14)}
    this.interact('circuit-1','RESTORE CIRCUIT 01',v3(-23,-18,-6));this.interact('circuit-2','RESTORE CIRCUIT 02',v3(23,-18,-6));this.interact('circuit-3','RESTORE CIRCUIT 03',v3(-23,-18,28));this.interact('circuit-4','RESTORE CIRCUIT 04',v3(23,-18,28));this.interact('archive','RECOVER ECLIPSE ARCHIVE',v3(0,-18,-36));this.interact('upgrade-hidden','INSTALL LATTICE MODULE',v3(-14,-18,38));this.interact('reactor','INTERFACE WITH REACTOR',v3(24,-18,44));
    const core=sphere(5,this.materials.cyan,24);core.position.set(0,-11,-36);core.material.emissiveIntensity=3.2;this.add(core);for(let i=0;i<8;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(7+i*.85,.12,8,48),this.materials.cyan);ring.position.copy(core.position);ring.rotation.set(Math.random(),Math.random(),Math.random());this.add(ring)}
    for(let i=0;i<70;i++){const junk=box(.3+Math.random()*.8,.2+Math.random()*.5,.3+Math.random()*1.2,this.materials.metal);junk.position.set((Math.random()-.5)*62,-19.4,(Math.random()-.5)*72+12);junk.rotation.set(Math.random()*TAU,Math.random()*TAU,Math.random()*TAU);this.add(junk)}
  }
}

class Player{
  constructor(scene,input,audio,vfx,save){this.scene=scene;this.input=input;this.audio=audio;this.vfx=vfx;this.save=save;this.group=new THREE.Group();this.model=new THREE.Group();this.group.add(this.model);this.velocity=v3();this.health=100;this.stamina=100;this.energy=100;this.aiming=false;this.scanning=false;this.fireCD=0;this.reloadCD=0;this.stepT=0;this.yBase=0;this.lookYaw=0;this.lookPitch=.13;this.crouch=false;this.buildModel()}
  buildModel(){const body=mat(0x22313a,.53,.72), fabric=mat(0x121a20,.88,.05), glow=mat(C.cyan,.25,.2,C.cyan,2.2);const torso=box(1.2,1.55,.62,body);torso.position.y=1.45;this.model.add(torso);const chest=box(.82,.48,.07,glow,false);chest.position.set(0,1.54,-.34);this.model.add(chest);const head=sphere(.42,body,14);head.position.y=2.56;this.model.add(head);const visor=box(.6,.22,.04,glow,false);visor.position.set(0,2.56,-.4);this.model.add(visor);this.lLeg=box(.36,1.3,.4,fabric);this.rLeg=box(.36,1.3,.4,fabric);this.lLeg.position.set(-.3,.1,0);this.rLeg.position.set(.3,.1,0);this.model.add(this.lLeg,this.rLeg);this.lArm=box(.3,1.25,.3,fabric);this.rArm=box(.3,1.25,.3,fabric);this.lArm.position.set(-.82,1.42,0);this.rArm.position.set(.82,1.42,0);this.model.add(this.lArm,this.rArm);this.tool=box(.18,.18,.95,glow,false);this.tool.position.set(.93,1.18,-.4);this.tool.rotation.x=.18;this.model.add(this.tool)}
  get forward(){return v3(Math.sin(this.lookYaw),0,Math.cos(this.lookYaw)).normalize()}
  muzzle(){return this.group.position.clone().add(v3(0,1.5,0)).add(this.forward.clone().multiplyScalar(1.2))}
  update(dt,camera,groundY){const s=this.save.get(),sp=3.9*(this.crouch?.55:1);const sprint=this.input.down('Shift')&&!this.crouch&&this.stamina>2&&(this.input.down('KeyW')||this.input.down('KeyA')||this.input.down('KeyS')||this.input.down('KeyD'));if(sprint)this.stamina=Math.max(0,this.stamina-dt*(10-s.upgrades.stamina*1.7));else this.stamina=Math.min(100, this.stamina+dt*(6+s.upgrades.stamina*1.4));this.aiming=this.input.mouse.aim||this.input.touch.aim;this.scanning=this.input.down('KeyF')||this.input.touch.scan;
    let mx=(this.input.down('KeyD')?1:0)-(this.input.down('KeyA')?1:0), mz=(this.input.down('KeyS')?1:0)-(this.input.down('KeyW')?1:0);if(Math.hypot(this.input.touch.mx,this.input.touch.my)>.05){mx=this.input.touch.mx;mz=-this.input.touch.my}const len=Math.hypot(mx,mz)||1;mx/=len;mz/=len;const yaw=this.lookYaw;const dx=mx*Math.cos(yaw)-mz*Math.sin(yaw),dz=mx*Math.sin(yaw)+mz*Math.cos(yaw);const targetSpeed=sp*(sprint?1.55:1);this.velocity.x=lerp(this.velocity.x,dx*targetSpeed,smooth(dt,14));this.velocity.z=lerp(this.velocity.z,dz*targetSpeed,smooth(dt,14));if(!mx&&!mz){this.velocity.x=lerp(this.velocity.x,0,smooth(dt,18));this.velocity.z=lerp(this.velocity.z,0,smooth(dt,18))}
    if((this.input.down('Space')||this.input.touch.jump)&&Math.abs(this.group.position.y-groundY)<.15){this.velocity.y=6.6;this.input.setKey('Space',false);this.input.touch.jump=false;this.audio.tone(360,.05,'triangle',.015)}this.velocity.y-=18*dt;this.group.position.addScaledVector(this.velocity,dt);this.group.position.x=clamp(this.group.position.x,-54,54);this.group.position.z=clamp(this.group.position.z,-82,86);if(this.group.position.y<groundY){this.group.position.y=groundY;this.velocity.y=0}if(sprint&&Math.hypot(this.velocity.x,this.velocity.z)>3){this.stepT-=dt;if(this.stepT<=0){this.audio.foot(this.group.position.y< -3?'metal':'concrete');this.stepT=.34}}
    const lookScale=(this.aiming?.0032:.0048)*(innerWidth<900?1.5:1);this.lookYaw-=this.input.mouse.dx*lookScale;this.lookPitch=clamp(this.lookPitch-this.input.mouse.dy*lookScale,-.22,.46);const lt=this.input.touch.lx||0,ly=this.input.touch.ly||0;if(Math.hypot(lt,ly)>.06){this.lookYaw-=lt*.045;this.lookPitch=clamp(this.lookPitch-ly*.035,-.3,.5)}this.group.rotation.y=this.lookYaw;this.fireCD=Math.max(0,this.fireCD-dt);this.reloadCD=Math.max(0,this.reloadCD-dt);if(this.input.down('KeyR')||this.input.touch.reload){this.reloadCD=Math.max(0,this.reloadCD-dt);if(this.reloadCD<=0){this.energy=Math.min(100,this.energy+dt*(28+s.upgrades.recharge*10));this.input.setKey('KeyR',false);this.input.touch.reload=false}} else {this.energy=Math.min(100,this.energy+dt*(6+s.upgrades.efficiency*2.5))}
    const moving=Math.hypot(this.velocity.x,this.velocity.z)>.4;const runBob=Math.sin(performance.now()*.012*(sprint?1.7:1))* (moving?.07:0);this.model.position.y=runBob;this.lLeg.rotation.x=Math.sin(performance.now()*.012*(sprint?1.7:1))* (moving?.45:0);this.rLeg.rotation.x=-this.lLeg.rotation.x;this.lArm.rotation.x=-this.lLeg.rotation.x*.45;this.rArm.rotation.x=-this.rLeg.rotation.x*.45;this.crouch=this.input.down('Control')||this.input.touch.crouch;this.model.scale.y=lerp(this.model.scale.y,this.crouch?.74:1,smooth(dt,14));
  }
  canFire(){return this.fireCD<=0&&this.energy>2}
  fire(){if(!this.canFire())return false;this.fireCD=.17;this.energy=Math.max(0,this.energy-5+this.save.get().upgrades.efficiency);this.audio.shot();this.vfx.burst(this.muzzle(),C.cyan,9,.5);this.vfx.ring(this.muzzle(),C.cyan,.18);return true}
}

class Enemy{
  constructor(scene,player,audio,vfx,kind,pos){this.scene=scene;this.player=player;this.audio=audio;this.vfx=vfx;this.kind=kind;this.group=new THREE.Group();this.group.position.copy(pos);this.hp=this.maxHp=this.kind==='SCOUT'?55:this.kind==='GUARD'?95:this.kind==='HEAVY'?190:450;this.state='PATROL';this.dead=false;this.phase=1;this.alert=0;this.attackCD=Math.random();this.pathT=Math.random()*TAU;this.build()}
  build(){const core=mat(this.kind==='CORE'?0x453149:this.kind==='HEAVY'?0x3c454b:0x283941,.35,.75),glow=mat(this.kind==='CORE'?0xff6d8d:C.red,.25,.3,this.kind==='CORE'?0xd52f5c:C.red,this.kind==='CORE'?4:2.6);if(this.kind==='SCOUT'){const body=sphere(.8,core,12);this.group.add(body);for(let i=0;i<4;i++){const arm=box(1.8,.12,.16,core);arm.rotation.y=i*Math.PI/2;this.group.add(arm)}const eye=sphere(.18,glow,8);eye.position.z=.7;this.group.add(eye)}else if(this.kind==='GUARD'){const body=box(1.3,1.8,1,core);body.position.y=1.1;this.group.add(body);const head=sphere(.38,core,10);head.position.y=2.35;this.group.add(head);const eye=box(.45,.12,.05,glow,false);eye.position.set(0,2.35,-.38);this.group.add(eye);for(const sx of [-.75,.75]){const arm=box(.35,1.35,.35,core);arm.position.set(sx,1.1,0);this.group.add(arm)}}else if(this.kind==='HEAVY'){const body=box(2.2,2.6,1.8,core);body.position.y=1.35;this.group.add(body);for(const sx of [-1.35,1.35]){const shoulder=sphere(.5,glow,10);shoulder.position.set(sx,1.7,0);this.group.add(shoulder)}const weak= sphere(.28,glow,10);weak.position.set(0,2.15,-.95);this.group.add(weak)}else{const body=sphere(3.1,core,16);body.position.y=3.1;this.group.add(body);for(let i=0;i<8;i++){const node=sphere(.36,glow,8);const a=i/8*TAU;node.position.set(Math.cos(a)*3.5,3+Math.sin(a*2)*1.2,Math.sin(a)*3.5);this.group.add(node)}this.group.userData.core=true}
    this.group.traverse(o=>{o.castShadow=true;o.receiveShadow=true});this.scene.add(this.group);this.baseY=this.group.position.y}
  update(dt){if(this.dead)return;const p=this.player.group.position;const d=this.group.position.distanceTo(p);const los=d<28;this.attackCD=Math.max(0,this.attackCD-dt);this.pathT+=dt; if(this.kind==='SCOUT'){if(los&&this.alert<1)this.alert+=dt*2;else this.alert=Math.max(0,this.alert-dt*.2);if(this.alert<.35){this.state='PATROL';this.group.position.x+=Math.cos(this.pathT)*.015;this.group.position.z+=Math.sin(this.pathT*1.4)*.015}else if(d<15){this.state='ATTACK';this.strafe(dt,d)}else{this.state='CHASING';this.seek(dt,.9)}} else if(this.kind==='GUARD'){if(los)this.alert=Math.min(1,this.alert+dt*1.8);else this.alert=Math.max(0,this.alert-dt*.14);if(this.alert<.25){this.state='PATROL';this.seekPatrol()}else if(d<14){this.state='ATTACKING';this.strafe(dt,d*.7)}else{this.state='CHASING';this.seek(dt,1.0)}} else if(this.kind==='HEAVY'){if(los)this.alert=Math.min(1,this.alert+dt);if(this.alert<.2){this.state='PATROL';this.seekPatrol()}else if(d<11){this.state='ATTACKING';this.attackHeavy(dt)}else{this.state='CHASING';this.seek(dt,.45)}} else {this.updateBoss(dt,d)}
    this.group.rotation.y=Math.atan2(p.x-this.group.position.x,p.z-this.group.position.z);if(d<2.2&&this.attackCD<=0&&this.kind!=='SCOUT'){this.hitPlayer()}this.group.position.y=this.baseY+(this.kind==='SCOUT'?Math.sin(this.pathT*3)*.4:Math.sin(this.pathT*1.7)*.06)}
  seek(dt,speed){const p=this.player.group.position,d=v3(p.x-this.group.position.x,0,p.z-this.group.position.z).normalize();this.group.position.addScaledVector(d,speed*dt*(this.kind==='HEAVY'?1:2))}
  seekPatrol(){this.group.position.x+=Math.cos(this.pathT)*.01;this.group.position.z+=Math.sin(this.pathT*.7)*.01}
  strafe(dt,d){const p=this.player.group.position,dv=v3(p.x-this.group.position.x,0,p.z-this.group.position.z).normalize(),side=v3(-dv.z,0,dv.x);this.group.position.addScaledVector(side,Math.sin(this.pathT*1.7)*dt*.9);if(d<7&&this.attackCD<=0)this.fireAtPlayer()}
  attackHeavy(dt){if(this.attackCD<=0){this.fireAtPlayer();this.vfx.ring(this.group.position,C.red,1.4);this.attackCD=2.3}this.seek(dt,.25)}
  fireAtPlayer(){this.attackCD=this.kind==='SCOUT'?1.25:this.kind==='GUARD'?1.7:2.6;const d=this.group.position.distanceTo(this.player.group.position);if(d<22){const dmg=this.kind==='HEAVY'?15:this.kind==='GUARD'?8:6;this.playerDamage(dmg);const dir=this.player.group.position.clone().sub(this.group.position).normalize();this.vfx.burst(this.player.group.position.clone().add(v3(0,1,0)),C.red,8,.4);this.audio.impact()}}
  hitPlayer(){if(this.attackCD<=0){this.attackCD=1.5;this.playerDamage(this.kind==='CORE'?22:this.kind==='HEAVY'?14:8)}}
  playerDamage(n){const resist=this.player.save.get().upgrades.resistance*.12;this.player.health=Math.max(0,this.player.health-n*(1-resist));this.audio.hurt();this.vfx.ring(this.player.group.position,C.red,.5);$('damage-flash').classList.add('hurt');setTimeout(()=>$('damage-flash').classList.remove('hurt'),130)}
  updateBoss(dt,d){const p=this.player.group.position;this.alert=1;if(this.phase===1){this.state=d<14?'ATTACKING':'CHASING';if(d>8)this.seek(dt,.8);if(this.attackCD<=0){this.bossVolley(3);this.attackCD=2.4}if(this.hp<this.maxHp*.58){this.phase=2;this.vfx.burst(this.group.position,C.amber,55,2.8);this.audio.alarm()}}else if(this.phase===2){this.state='HUNTING';if(d>10)this.seek(dt,1.05);else this.strafe(dt,d);if(this.attackCD<=0){this.bossVolley(6);this.attackCD=1.6}if(this.hp<this.maxHp*.25){this.phase=3;this.audio.setMix(true);this.vfx.burst(this.group.position,C.cyan,65,3.5)}}else{this.state='OVERDRIVE';if(d>7)this.seek(dt,1.5);if(this.attackCD<=0){this.bossVolley(9);this.attackCD=.95}}this.group.userData.phase=this.phase}
  bossVolley(n){for(let i=0;i<n;i++){setTimeout(()=>{const p=this.player.group.position;if(this.group.position.distanceTo(p)<32)this.playerDamage(3+this.phase*1.5);this.vfx.ring(p,C.red,.22)},i*70)}this.audio.alarm()}
  takeDamage(n,point){if(this.dead)return;const mult=this.kind==='CORE'&&this.phase===2?.7:1;this.hp-=n*mult;this.vfx.burst(point||this.group.position,C.cyan,11,.7);this.audio.impact();if(this.hp<=0){this.dead=true;this.state='DEFEATED';this.vfx.burst(this.group.position,C.red,this.kind==='CORE'?90:36,this.kind==='CORE'?3.6:1.5);this.vfx.ring(this.group.position,C.cyan,this.kind==='CORE'?3:1);this.audio.confirm();}}
}

class Game{
  constructor(){this.save=new SaveManager();this.input=new Input(document.querySelector('#game'));this.audio=new AudioEngine();this.vfx=null;this.state='BOOT';this.mission=this.save.get().mission;this.objective=this.save.get().objective;this.enemies=[];this.world=null;this.player=null;this.camera=null;this.renderer=null;this.clock=new THREE.Clock();this.scanEnergy=100;this.scanToggle=false;this.missionTimers={};this.puzzleOpen=false;this.menuOrbit=0;this.panelReturn='MENU';this.init()}
  init(){this.renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance',alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.45));this.renderer.setSize(innerWidth,innerHeight);this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.14;this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;document.querySelector('#game').appendChild(this.renderer.domElement);this.scene=new THREE.Scene();this.scene.background=new THREE.Color(0x050a0f);this.scene.fog=new THREE.FogExp2(0x071019,.0105);this.camera=new THREE.PerspectiveCamera(64,innerWidth/innerHeight,.1,320);this.vfx=new VFX(this.scene);this.lights();this.world=new World(this.scene);this.player=new Player(this.scene,this.input,this.audio,this.vfx,this.save);this.player.group.position.set(0,0.1,62);this.player.group.visible=false;this.setupUI();this.setupTouch();this.applySettings(this.save.get().settings);window.addEventListener('resize',()=>this.resize());setTimeout(()=>{this.showMenu();$('boot').classList.add('hidden')},850);this.renderer.setAnimationLoop(()=>this.frame());}
  lights(){const hemi=new THREE.HemisphereLight(0x91b4c8,0x101417,.72);this.scene.add(hemi);const sun=new THREE.DirectionalLight(0xdcecff,2.15);sun.position.set(-50,85,35);sun.castShadow=true;sun.shadow.mapSize.set(1536,1536);sun.shadow.camera.left=-120;sun.shadow.camera.right=120;sun.shadow.camera.top=120;sun.shadow.camera.bottom=-120;sun.shadow.camera.far=240;this.scene.add(sun);this.sun=sun;const blue=new THREE.PointLight(C.blue,32,90,2);blue.position.set(0,12,-24);this.scene.add(blue);}
  setupUI(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>this.action(b.dataset.action)));this.menuContinue.disabled=!this.save.hasSave();}
  get menuContinue(){return document.querySelector('[data-action="continue"]')}
  action(a){this.audio.unlock();this.audio.ui();if(a==='new')this.newGame();else if(a==='continue')this.continueGame();else if(a==='settings')this.settings();else if(a==='controls')this.controls();else if(a==='credits')this.credits();else if(a==='resume')this.resume();else if(a==='inventory')this.inventory();else if(a==='menu')this.quitToMenu()}
  showMenu(){$('menu').classList.remove('hidden');$('hud').classList.add('hidden');$('pause').classList.add('hidden');$('panel').classList.add('hidden');$('mobile-controls').classList.add('hidden');this.state='MENU';this.player.group.visible=false;this.input.mouse.down=false;document.exitPointerLock?.();}
  newGame(){this.save.reset();this.mission=1;this.objective=0;this.enterPlay(true)}
  continueGame(){const d=this.save.get();this.mission=d.mission||1;this.objective=d.objective||0;this.enterPlay(false)}
  enterPlay(fresh){this.audio.unlock();this.state='PLAYING';this.player.group.visible=true;const d=this.save.get();this.player.health=d.player.health||100;this.player.stamina=d.player.stamina||100;this.player.energy=d.player.energy||100;this.player.group.position.set(d.player.x,d.player.y,d.player.z);if(fresh)this.player.group.position.set(0,.1,62);this.input.mouse.dx=0;this.input.mouse.dy=0;$('menu').classList.add('hidden');$('hud').classList.remove('hidden');$('mobile-controls').classList.remove('hidden');$('pause').classList.add('hidden');$('panel').classList.add('hidden');this.setupMission();this.respawnEnemies();this.updateHUD();this.showToast(fresh?'FIELD LINK ESTABLISHED':'SESSION RESTORED');if(fresh)this.dialog('FIELD CONTROL','Signal is stable.','No human signatures detected inside Helix. Proceed alone.')}
  setupMission(){const m=MISSIONS[this.mission];$('mission-id').textContent=`MISSION ${String(m.id).padStart(2,'0')}`;$('mission-title').textContent=m.title;$('objective').textContent=m.objective;$('region').textContent=m.region}
  respawnEnemies(){for(const e of this.enemies)this.scene.remove(e.group);this.enemies=[];const list=[];if(this.mission===2||this.mission===3)list.push(['SCOUT',v3(13,2.5,18)],['SCOUT',v3(-15,2.5,-10)]);if(this.mission>=4&&this.mission<=6)list.push(['GUARD',v3(-16,-18,10)],['GUARD',v3(15,-18,22)],['HEAVY',v3(28,-18,-8)]);if(this.mission===8)list.push(['CORE',v3(24,-15,48)]);for(const [k,p] of list)this.enemies.push(new Enemy(this.scene,this.player,this.audio,this.vfx,k,p));this.audio.setMix(this.mission>=4)}
  pause(){if(this.state!=='PLAYING')return;this.state='PAUSED';document.exitPointerLock?.();$('pause').classList.remove('hidden')}
  resume(){this.state='PLAYING';$('pause').classList.add('hidden');$('panel').classList.add('hidden');if(innerWidth>900)document.querySelector('#game canvas')?.requestPointerLock()}
  quitToMenu(){this.saveCheckpoint();this.showMenu()}
  saveCheckpoint(){this.save.update(d=>{d.mission=this.mission;d.objective=this.objective;d.player={x:this.player.group.position.x,y:this.player.group.position.y,z:this.player.group.position.z,health:this.player.health,stamina:this.player.stamina,energy:this.player.energy}});this.showToast('AUTOSAVE // CHECKPOINT')}
  showToast(t,ms=1400){const el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(this.toastT);this.toastT=setTimeout(()=>el.classList.remove('show'),ms)}
  dialog(head,title,body){this.state='PAUSED';$('panel-content').innerHTML=`<div class="overline">${head}</div><h2>${title}</h2><div class="card"><p>${body}</p></div><button class="menu-btn" id="dialog-ok" style="margin-top:16px">ACKNOWLEDGE</button>`;$('panel').classList.remove('hidden');$('dialog-ok').onclick=()=>{this.state='PLAYING';$('panel').classList.add('hidden');if(innerWidth>900)document.querySelector('#game canvas')?.requestPointerLock()};}
  complete(){this.saveCheckpoint();this.audio.confirm();this.objective=0;if(this.mission<8){this.mission++;this.save.update(d=>{d.mission=this.mission;d.objective=0});this.setupMission();this.respawnEnemies();this.player.health=100;this.player.energy=100;this.showToast(`MISSION ${String(this.mission).padStart(2,'0')} // ${MISSIONS[this.mission].title}`,2200)}else this.ending()}
  settings(){this.panelReturn=this.state==='MENU'?'MENU':'PLAYING';this.state='PAUSED';const s=this.save.get().settings;$('panel-content').innerHTML=`<div class="overline">SYSTEM CONFIGURATION</div><h2>SETTINGS</h2><div class="settings-grid"><div class="setting"><label>GRAPHICS PRESET</label><select id="set-graphics"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>ULTRA</option></select></div><div class="setting"><label>UI SCALE</label><input id="set-ui" type="range" min="0.85" max="1.25" step="0.05" value="${s.uiScale}"></div><div class="setting"><label>MASTER</label><input id="set-master" type="range" min="0" max="1" step="0.01" value="${s.master}"></div><div class="setting"><label>MUSIC</label><input id="set-music" type="range" min="0" max="1" step="0.01" value="${s.music}"></div><div class="setting"><label>SFX</label><input id="set-sfx" type="range" min="0" max="1" step="0.01" value="${s.sfx}"></div><div class="setting"><label>REDUCED MOTION</label><select id="set-motion"><option value="false">OFF</option><option value="true">ON</option></select></div><div class="setting"><label>SUBTITLES</label><select id="set-sub"><option value="true">ON</option><option value="false">OFF</option></select></div></div><button class="menu-btn" id="set-save" style="margin-top:18px">APPLY & RETURN</button>`;$('set-graphics').value=s.graphics;$('set-motion').value=String(s.reducedMotion);$('set-sub').value=String(s.subtitles);$('set-save').onclick=()=>{this.save.update(d=>{d.settings.graphics=$('set-graphics').value;d.settings.uiScale=Number($('set-ui').value);d.settings.master=Number($('set-master').value);d.settings.music=Number($('set-music').value);d.settings.sfx=Number($('set-sfx').value);d.settings.reducedMotion=$('set-motion').value==='true';d.settings.subtitles=$('set-sub').value==='true'});this.applySettings(this.save.get().settings);$('panel').classList.add('hidden');if(this.panelReturn==='MENU')this.showMenu();else this.resume()};$('panel').classList.remove('hidden')}
  controls(){this.panelReturn=this.state==='MENU'?'MENU':'PLAYING';this.state='PAUSED';$('panel-content').innerHTML=`<div class="overline">FIELD INPUT MAP</div><h2>CONTROLS</h2><div class="card"><p><b>WASD</b> move · <b>SHIFT</b> sprint · <b>SPACE</b> jump · <b>CTRL</b> crouch · <b>E</b> interact · <b>F</b> scanner · <b>R</b> recharge · <b>TAB</b> inventory · <b>ESC</b> pause · <b>LEFT MOUSE</b> fire · <b>RIGHT MOUSE</b> aim.</p><p>Gamepad and touch controls are enabled automatically on supported devices.</p></div><button class="menu-btn" id="close-panel">RETURN</button>`;$('close-panel').onclick=()=>{if(this.panelReturn==='MENU')this.showMenu();else this.resume()};$('panel').classList.remove('hidden')}
  credits(){this.panelReturn=this.state==='MENU'?'MENU':'PLAYING';this.state='PAUSED';$('panel-content').innerHTML=`<div class="overline">HELIX FIELD EDITION</div><h2>CREDITS</h2><div class="card"><h3>PROJECT ECLIPSE</h3><p>Original concept, procedural environment, gameplay systems, UI, VFX and synthesized audio created for this browser experience.</p><p>3D runtime: Three.js, MIT License. No proprietary game assets are used.</p></div><button class="menu-btn" id="close-panel">RETURN</button>`;$('close-panel').onclick=()=>this.panelReturn==='MENU'?this.showMenu():this.resume();$('panel').classList.remove('hidden')}
  inventory(){this.state='PAUSED';const d=this.save.get(),inv=d.inventory,u=d.upgrades;const cell=inv['Energy Cell']||0;const upgrades=`Health ${u.health}/3 · Stamina ${u.stamina}/3 · Resistance ${u.resistance}/3 · Output ${u.damage}/3 · Efficiency ${u.efficiency}/3 · Recharge ${u.recharge}/3 · Scan Radius ${u.scanRadius}/3 · Scan Duration ${u.scanDuration}/3`;$('panel-content').innerHTML=`<div class="overline">FIELD INVENTORY</div><h2>INVENTORY</h2><div class="inventory-grid"><div class="item"><b>ENERGY CELLS</b><span>${cell}</span></div><div class="item"><b>DOCUMENTS</b><span>${inv['Research Document']||0}</span></div><div class="item"><b>ARCHIVE</b><span>${inv['ECLIPSE ARCHIVE']||0}</span></div></div><div class="card" style="margin-top:12px"><h3>UPGRADES</h3><p>${upgrades}</p><button class="menu-btn" id="upgrade" style="margin-top:8px">INSTALL NEXT LATTICE MODULE</button></div><button class="menu-btn" id="close-panel" style="margin-top:12px">RETURN</button>`;$('upgrade').onclick=()=>this.buyUpgrade();$('close-panel').onclick=()=>this.resume();$('panel').classList.remove('hidden')}
  buyUpgrade(){const d=this.save.get();const keys=['health','stamina','damage','efficiency','recharge','scanRadius','scanDuration'];const key=keys.find(k=>d.upgrades[k]<3);if(!key){this.showToast('ALL MODULES AT MAXIMUM CAPACITY');return}const lvl=d.upgrades[key]+1,cost=lvl*2;if((d.inventory['Energy Cell']||0)<cost){this.showToast(`REQUIRES ${cost} ENERGY CELLS`);return}this.save.update(s=>{s.inventory['Energy Cell']-=cost;s.upgrades[key]=lvl});this.audio.confirm();this.showToast(`${key.toUpperCase()} // LEVEL ${lvl}`);this.inventory()}
  interact(){const it=this.nearestInteractable();if(!it)return;this.audio.unlock();const id=it.id;const d=this.save.get();if(id==='gate'&&this.mission===1){this.objective=1;this.complete();return}if(id.startsWith('relay-')&&this.mission===2){if(d.relays[id])return;this.save.update(s=>s.relays[id]=true);this.audio.confirm();this.vfx.burst(it.object.position.clone().add(v3(0,1,0)),C.cyan,28,.8);const count=Object.keys(this.save.get().relays).length;this.showToast(`FIELD RELAY ${id.slice(-1).toUpperCase()} ONLINE`);if(count>=3)this.complete();return}if(id==='tower-uplink'&&this.mission===3){this.openPuzzle();return}if(id==='elevator'&&this.mission===4){this.player.group.position.set(0,-19.5,24);this.audio.alarm();this.vfx.burst(this.player.group.position,C.cyan,38,1.2);this.complete();return}if(id.startsWith('circuit-')&&this.mission===5){if(d.circuits[id])return;this.save.update(s=>s.circuits[id]=true);this.audio.confirm();this.vfx.burst(it.object.position,C.amber,20,.7);if(Object.keys(this.save.get().circuits).length>=4)this.complete();return}if(id==='archive'&&this.mission===6){this.save.update(s=>{s.inventory['ECLIPSE ARCHIVE']=(s.inventory['ECLIPSE ARCHIVE']||0)+1;s.collectibles.push('archive-01')});this.audio.pickup();this.dialog('RECOVERED AUDIO LOG','THE DEFINITION OF INSIDE','We did not lose containment. We lost the definition of inside and outside. The field folded the facility around its own memory.');setTimeout(()=>{if(this.state==='PAUSED'){this.complete()}},500);return}if(id==='upgrade-hidden'&&this.mission===5){this.save.update(s=>{s.upgrades.resistance=Math.max(s.upgrades.resistance,1);s.upgrades.scanRadius=Math.max(s.upgrades.scanRadius,1)});this.audio.confirm();this.showToast('LATTICE SHELL INSTALLED');return}if(id==='reactor'&&(this.mission===7||this.mission===8)){if(this.mission===7){this.complete();this.showToast('CONTAINMENT ARRAY UNSEALED',1800);return}if(this.mission===8&&this.enemies.every(e=>e.dead)){this.ending()}}
  }
  nearestInteractable(){const p=this.player.group.position;let best=null,bd=2.4;for(const it of this.world.interactables){if(!it.enabled||!it.object.visible)continue;const w=it.object.getWorldPosition(v3());const d=w.distanceTo(p);if(d<bd){bd=d;best=it}}return best}
  updateScanner(){const active=this.player.scanning;if(active){this.scanEnergy-=.1;this.scanEnergy=Math.max(0,this.scanEnergy)}else this.scanEnergy=Math.min(100,this.scanEnergy+.08);$('scanner').classList.toggle('hidden',!active);for(const it of this.world.interactables){const dist=it.object.position.distanceTo(this.player.group.position);const mark=active&&dist<15+this.save.get().upgrades.scanRadius*4;it.object.children[0].material.opacity=mark?.65:.16;it.object.scale.setScalar(mark?1.35:1)}}
  openPuzzle(){this.puzzleOpen=true;this.state='PAUSED';document.exitPointerLock?.();$('panel-content').innerHTML=`<div class="overline">UPLINK ARRAY // SIGNAL SYNCHRONIZATION</div><h2>FREQUENCY LOCK</h2><div class="card"><p>Align the carrier marker with the Helix pulse. The target moves continuously; press LOCK when the two bands overlap.</p><div id="puzzle-track" style="position:relative;height:48px;border:1px solid rgba(135,214,255,.2);margin:18px 0;background:linear-gradient(90deg,#061018,#102734,#061018)"><i id="p-target" style="position:absolute;top:5px;width:2px;height:36px;background:#9ce9ff;box-shadow:0 0 16px #5ccfff"></i><b id="p-cursor" style="position:absolute;top:0;width:16px;height:46px;border:1px solid #ffb55d"></b></div><button class="menu-btn" id="lock">LOCK SIGNAL</button></div>`;$('panel').classList.remove('hidden');let start=performance.now(),done=false;const loop=()=>{if(done||!this.puzzleOpen)return;const t=(performance.now()-start)/1000;const target=(Math.sin(t*1.3)*.5+.5)*100;const cursor=(Math.sin(t*2.1+.9)*.5+.5)*100;$('p-target').style.left=`calc(${target}% - 1px)`;$('p-cursor').style.left=`calc(${cursor}% - 8px)`;this.puzzleRAF=requestAnimationFrame(loop)};loop();$('lock').onclick=()=>{done=true;cancelAnimationFrame(this.puzzleRAF);const t=(performance.now()-start)/1000;const target=(Math.sin(t*1.3)*.5+.5)*100,cursor=(Math.sin(t*2.1+.9)*.5+.5)*100;this.puzzleOpen=false;if(Math.abs(target-cursor)<12){this.audio.puzzle();$('panel').classList.add('hidden');this.state='PLAYING';this.complete();this.dialog('UPLINK RESPONSE','SIGNAL ACQUIRED','A transmission is repeating from beneath the facility. It contains your own biometric signature.');}else{this.audio.error();this.showToast('LOCK FAILED — CARRIER MISALIGNED');}}}
  handleShot(){const origin=this.player.muzzle();const dir=this.player.forward.clone();const ray=new THREE.Raycaster(origin,dir,0,34);const targets=[];for(const e of this.enemies){if(!e.dead)e.group.traverse(o=>targets.push(o))}const hit=ray.intersectObjects(targets,false)[0];if(!hit)return;const enemy=this.enemies.find(e=>{let ok=false;e.group.traverse(o=>{if(o===hit.object)ok=true});return ok});if(enemy){let dmg=16*(1+this.save.get().upgrades.damage*.16);if(this.player.aiming)dmg*=1.24;if(enemy.kind==='CORE'&&enemy.phase===2)dmg*=.72;enemy.takeDamage(dmg,hit.point)}}
  ending(){this.state='ENDING';document.exitPointerLock?.();$('hud').classList.add('hidden');$('mobile-controls').classList.add('hidden');let a=0;const step=()=>{a=Math.min(1,a+.008);this.camera.position.lerp(v3(31,-5,40),.01);this.camera.lookAt(v3(24,-12,46));if(a<1)requestAnimationFrame(step);else this.finalPanel()};step()}
  finalPanel(){this.save.update(d=>{d.mission=8;d.objective=99});$('panel-content').innerHTML=`<div class="overline">ZERO CHAMBER // CONTAINMENT COMPLETE</div><h2>AFTERIMAGE</h2><div class="card"><h3>THE FINAL RECORD</h3><p>The catastrophe was not an explosion. Helix built a machine that could borrow energy from future states, and the facility became the first place those states overlapped. The security intelligence was not protecting the reactor from you; it was protecting reality from the reactor.</p><p>You restored a boundary instead of destroying the machine. Above the mountain, the storm opens for one impossible second. A final signal repeats the moment before the breach — and the voice on it is yours.</p></div><button class="menu-btn" id="ending-credits" style="margin-top:14px">CREDITS</button><button class="menu-btn" id="ending-menu" style="margin-top:8px">RETURN TO MAIN MENU</button>`;$('ending-credits').onclick=()=>this.credits();$('ending-menu').onclick=()=>{this.save.reset();this.showMenu()};$('panel').classList.remove('hidden')}
  updateHUD(){const p=this.player,d=this.save.get();$('health-bar').style.width=`${p.health}%`;$('stamina-bar').style.width=`${p.stamina}%`;$('energy-bar').style.width=`${this.scanEnergy}%`;$('health-text').textContent=Math.round(p.health);$('stamina-text').textContent=Math.round(p.stamina);$('energy-text').textContent=Math.round(this.scanEnergy);$('weapon-readout').textContent=p.energy>20?'CHARGED':'RECHARGE';const it=this.nearestInteractable();$('interaction').classList.toggle('hidden',!it);if(it)$('interaction').innerHTML=`<span>[E]</span><strong>${it.label}</strong>`;}
  gamepad(){const pads=navigator.getGamepads?.()||[];const p=pads.find(Boolean);if(!p)return;this.input.touch.mx=p.axes[0]||0;this.input.touch.my=p.axes[1]||0;this.input.touch.lx=p.axes[2]||0;this.input.touch.ly=p.axes[3]||0;this.input.touch.fire=!!p.buttons[7]?.pressed;this.input.touch.aim=!!p.buttons[6]?.pressed;this.input.touch.jump=!!p.buttons[0]?.pressed;if(p.buttons[2]?.pressed)this.input.setKey('KeyE',true);}
  resize(){this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix();this.renderer.setSize(innerWidth,innerHeight);this.applySettings(this.save.get().settings)}
  applySettings(s){this.renderer.setPixelRatio(Math.min(devicePixelRatio,({LOW:.82,MEDIUM:1.0,HIGH:1.28,ULTRA:1.45}[s.graphics]||1.0)));this.renderer.toneMappingExposure={LOW:1.02,MEDIUM:1.08,HIGH:1.14,ULTRA:1.2}[s.graphics]||1.1;document.documentElement.style.setProperty('--ui-scale',s.uiScale);this.audio.master=s.master;this.audio.music=s.music;this.audio.sfx=s.sfx;this.audio.ambience=s.master*.9}
  updateCamera(dt){const p=this.player.group.position;const forward=this.player.forward;const distance=this.player.aiming?4.1:6.8;const shoulder=this.player.aiming?.65:.95;const target=p.clone().add(v3(0,this.player.crouch?1.5:2.1,0)).add(forward.clone().multiplyScalar(-distance)).add(v3(Math.cos(this.player.lookYaw)*shoulder,0,-Math.sin(this.player.lookYaw)*shoulder));this.camera.position.lerp(target,v3().set(smooth(dt,10),smooth(dt,10),smooth(dt,10)));this.camera.lookAt(p.clone().add(v3(0,this.player.aiming?1.8:1.65,0)).add(forward.clone().multiplyScalar(4)));}
  frame(){const dt=Math.min(.032,this.clock.getDelta());this.gamepad();if(this.state==='MENU'){this.menuOrbit+=dt*.16;this.camera.position.set(Math.sin(this.menuOrbit)*42,12,46-Math.cos(this.menuOrbit)*24);this.camera.lookAt(v3(0,5,-18));this.renderer.render(this.scene,this.camera);this.vfx.update(dt);this.input.clearDelta();return}if(this.state==='PLAYING'){if(this.input.down('Escape')){this.input.setKey('Escape',false);this.pause()}if(this.input.down('Tab')){this.input.setKey('Tab',false);this.inventory()}if(this.input.down('KeyE')){this.input.setKey('KeyE',false);this.interact()}if(this.input.down('KeyF')&&this.scanToggle===false){this.scanToggle=true;this.player.scanning=!this.player.scanning}if(!this.input.down('KeyF'))this.scanToggle=false;if(this.scanEnergy<=0)this.player.scanning=false;this.player.update(dt,this.camera,this.mission>=4?-19.5:.1);if((this.input.mouse.down||this.input.touch.fire)&&this.player.fire()){this.handleShot()}this.updateCamera(dt);this.updateScanner();for(const e of this.enemies)e.update(dt);this.enemies=this.enemies.filter(e=>{if(e.dead){this.scene.remove(e.group);if(e.kind==='CORE'){this.showToast('CORE WARDEN // DEFEATED',1800);this.mission=8;this.save.update(d=>d.mission=8)}return false}return true});if(this.mission===8&&this.enemies.length===0&&this.player.group.position.distanceTo(v3(24,-15,48))<12){this.showToast('REACTOR ACCESS OPEN');this.objective=1}if(this.player.health<=0){this.player.health=100;this.player.group.position.set(0,this.mission>=4?-19.5:.1,this.mission>=4?24:4);this.saveCheckpoint();this.showToast('CHECKPOINT RESTORED');this.respawnEnemies()}this.updateHUD();this.sun.position.x=-50+Math.sin(performance.now()*.00009)*24;this.sun.position.z=35+Math.cos(performance.now()*.00007)*18;this.sun.intensity=1.92+Math.sin(performance.now()*.00018)*.08;}else if(this.state==='ENDING'){this.vfx.update(dt)}else if(this.state==='PAUSED'){this.vfx.update(dt)}this.vfx.update(dt);this.renderer.render(this.scene,this.camera);this.input.clearDelta()}
  setupTouch(){const root=$('mobile-controls');const bindStick=(el,keyx,keyy)=>{let active=false;const i=el.querySelector('i');const go=e=>{active=true;el.setPointerCapture?.(e.pointerId);move(e)};const move=e=>{if(!active)return;const r=el.getBoundingClientRect(),x=(e.clientX-(r.left+r.width/2))/(r.width*.38),y=(e.clientY-(r.top+r.height/2))/(r.height*.38);const m=Math.hypot(x,y)||1;const nx=clamp(x/m,-1,1)*Math.min(1,m),ny=clamp(y/m,-1,1)*Math.min(1,m);this.input.touch[keyx]=nx;this.input.touch[keyy]=ny;i.style.transform=`translate(calc(-50% + ${nx*30}px),calc(-50% + ${ny*30}px))`};const end=()=>{active=false;this.input.touch[keyx]=0;this.input.touch[keyy]=0;i.style.transform='translate(-50%,-50%)'};el.addEventListener('pointerdown',go);el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)};bindStick($('stick-move'),'mx','my');bindStick($('stick-look'),'lx','ly');const hold=(id,key)=>{const el=$(id);el.addEventListener('pointerdown',()=>this.input.touch[key]=true);const end=()=>this.input.touch[key]=false;el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('pointerleave',end)};hold('btn-fire','fire');hold('btn-aim','aim');hold('btn-jump','jump');hold('btn-scan','scan');$('btn-interact').addEventListener('pointerdown',()=>this.interact());hold('btn-crouch','crouch');root.addEventListener('pointerdown',()=>this.audio.unlock(),{passive:true})}
}

function bootFailure(error){console.error(error);$('error').classList.remove('hidden');$('error').innerHTML=`<div class="error-card"><h2>PROJECT ECLIPSE // SYSTEM FAULT</h2><p>WebGL failed to initialize. Try a current Chrome, Edge, Firefox, or Safari browser with hardware acceleration enabled.</p><button class="menu-btn" onclick="location.reload()">REINITIALIZE</button></div>`}
try{new Game()}catch(error){bootFailure(error)}
